  `job_log_id` bigint NOT NULL COMMENT '任务日志ID',
  `job_id` bigint NOT NULL COMMENT '任务组ID',
  `node_id` bigint NOT NULL COMMENT '节点ID',
  `batch_id` varchar(128) DEFAULT NULL COMMENT '执行批次ID',
